// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        c = (new PredictTheBlockHashChallenge){value: 1 ether}();
    }
    function testFuzz_property(address caller, uint256 value, bytes32 hash) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        vm.deal(caller, value);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(caller);
        try c.lockInGuess{value: value}(hash) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertEq(address(c).balance - balanceBefore, 1 ether);
        }
    }
}
